    verfasser: VERFASSER,
    normen: ["§ 1 Abs. 1a Satz 3 UStG", "§ 15a Abs. 1 bis 6 und 10 UStG", "Abschn. 15a.2 Abs. 3 UStAE", "BStBl 1989 II S. 120"],
